sys_script_include.script:
var GetRetiredSWModels = Class.create();
GetRetiredSWModels.prototype = {
    initialize: function() {},

    getRetiredModels: function() {
        var retiredModels = new GlideRecord("cmdb_software_product_model");
        retiredModels.addEncodedQuery("status=Retired");
        retiredModels.query();

        var count = 0;
        var sysIds = [];

        while (retiredModels.next()) {
            count += 1;
            sysIds.push(retiredModels.getValue('sys_id'));
        }

        // Return the count and sys_ids as an object
        return {
            count: count,
            sys_ids: sysIds
        };
    },

    type: 'GetRetiredSWModels' // Name of the Script Include
};
